/**
 * The value nodes that make up a parsed document. Every node carries a `t`
 * tag naming its kind:
 *
 *   table    - a Map of key -> node, plus whether a `[name]` header has
 *              already made this exact table current (which blocks a second
 *              such header from naming it again).
 *   atot     - an array of tables (created by `[[name]]`); `arr` holds the
 *              table nodes in append order.
 *   array    - a plain value array; `arr` holds the item nodes in order.
 *   string   - `v` holds the decoded string.
 *   integer  - `raw` holds the sign and digits with underscores removed, so
 *              arbitrarily large integers survive without precision loss.
 *   float    - `v` holds the parsed JS number.
 *   boolean  - `v` holds true or false.
 */
export function makeTable() {
  return { t: 'table', map: new Map(), headerDefined: false }
}

export function makeRoot() {
  return makeTable()
}

/** Joins key names with `.`, exactly as they read after decoding. */
export function formatPath(names) {
  return names.join('.')
}

/**
 * Walks `names` from `root`, creating intermediate tables as needed, and
 * assigns `value` at the final name. `prefix` names the path from the
 * document root down to `root`, so error messages read as full paths.
 */
export function assignPath(root, names, value, prefix) {
  let node = root
  for (let i = 0; i < names.length - 1; i++) {
    const key = names[i]
    const existing = node.map.get(key)
    if (existing === undefined) {
      const table = makeTable()
      node.map.set(key, table)
      node = table
    } else if (existing.t === 'table') {
      node = existing
    } else if (existing.t === 'atot') {
      node = existing.arr[existing.arr.length - 1]
    } else {
      throw new ParseError(`${formatPath([...prefix, ...names.slice(0, i + 1)])} is not a table`)
    }
  }
  const lastKey = names[names.length - 1]
  if (node.map.has(lastKey)) {
    throw new ParseError(`key ${formatPath([...prefix, ...names])} is defined twice`)
  }
  node.map.set(lastKey, value)
}

/**
 * Walks `names` from the document `root` for a `[name]` or `[[name]]`
 * header, creating intermediate tables (or descending into the last element
 * of an array of tables) as needed, and returns the table that becomes
 * current.
 */
export function navigateHeader(root, names, isArrayOfTables) {
  let node = root
  for (let i = 0; i < names.length - 1; i++) {
    const key = names[i]
    const existing = node.map.get(key)
    if (existing === undefined) {
      const table = makeTable()
      node.map.set(key, table)
      node = table
    } else if (existing.t === 'table') {
      node = existing
    } else if (existing.t === 'atot') {
      node = existing.arr[existing.arr.length - 1]
    } else {
      throw new ParseError(`${formatPath(names.slice(0, i + 1))} is not a table`)
    }
  }

  const lastKey = names[names.length - 1]
  const existing = node.map.get(lastKey)
  const path = formatPath(names)

  if (isArrayOfTables) {
    let atot = existing
    if (atot === undefined) {
      atot = { t: 'atot', arr: [] }
      node.map.set(lastKey, atot)
    } else if (atot.t !== 'atot') {
      throw new ParseError(`${path} is not an array of tables`)
    }
    const table = makeTable()
    atot.arr.push(table)
    return table
  }

  if (existing === undefined) {
    const table = makeTable()
    table.headerDefined = true
    node.map.set(lastKey, table)
    return table
  }
  if (existing.t !== 'table') {
    throw new ParseError(`${path} is not a table`)
  }
  if (existing.headerDefined) {
    throw new ParseError(`table ${path} is defined twice`)
  }
  existing.headerDefined = true
  return existing
}
"}

