  switch (node.t) {
    case 'table':
      return renderEntries(sortedKeys(node).map((k) => [JSON.stringify(k), node.map.get(k)]), indent, '{', '}')
    case 'atot':
      return renderEntries(node.arr.map((item) => [null, item]), indent, '[', ']')
    case 'array':
