  if (entries.length === 0) return open + close
  const inner = indent + '  '
  const body = entries
    .map(([key, value]) => `${inner}${key !== null ? key + ': ' : ''}${render(value, inner)}`)
    .join(',\n')
  return `${open}\n${body}\n${indent}${close}`
}

